header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/audit.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/snapshot_service.php';require_once __DIR__.'/../reports/filing_archive_service.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405);$auth=requireAuth();$uid=authTenantId($auth);$actorId=authActorId($auth);$d=json_decode(file_get_contents('php://input'),true)?:[];$start=trim((string)($d['period_start']??''));$end=trim((string)($d['period_end']??''));$target=strtoupper(trim((string)($d['status']??'DRAFT')));$sd=DateTimeImmutable::createFromFormat('!Y-m-d',$start);$ed=DateTimeImmutable::createFromFormat('!Y-m-d',$end);if(!$sd||!$ed||$ed<$sd||!in_array($target,['DRAFT','REVIEWED','LOCKED','FILED'],true))throw new Exception('Invalid accounting period');$c=db();requirePermission($c,$uid,'accounting.periods.manage');$c->begin_transaction();
